arguments.dot:
digraph {
  rankdir=LR;
  node [shape=box, style=filled, fillcolor=lightblue];
  input [label="Input"];
  conv1 [label="Conv Layer\nk < n"];
  conv2 [label="Conv Layer\nk < n"];
  output [label="Output"];
  input -> conv1;
  conv1 -> conv2;
  conv2 -> output;
  subgraph cluster_notes {
    label="Problem: O(n/k) layers needed";
    style=dashed;
    note [label="Distant positions\nnot connected", shape=ellipse, fillcolor=lightyellow];
    input -> note [style=invis];
    output -> note [style=invis];
  }
}
